arguments.new_string:
else:
    try:
        defaults_n = len(func.__defaults__)
    except (AttributeError, TypeError):
        defaults_n = 0
    try:
        names = func.__code__.co_varnames
        n = func.__code__.co_argcount
        required_n = n - defaults_n
        required_names = set(names[:required_n])

        # Check for keyword-only arguments (Python 3)
        kwonly_count = 0
        try:
            if hasattr(func, '__kwdefaults__') and func.__kwdefaults__:
                # Count required keyword-only args (those without defaults)
                kwonly_defaults = func.__kwdefaults__
                # All kwonly args need to be counted if they have no default
                for name in kwonly_defaults.keys():
                    if name not in kwonly_defaults or kwonly_defaults[name] is EMPTY:
                        kwonly_count += 1
        except (AttributeError, TypeError):
            pass

        # If there are varargs they could be required, but all keywords args can't be
        max_n = required_n + 1 if func.__code__.co_flags & CO_VARARGS else n
        # Add keyword-only count to max_n
        max_n = max_n + kwonly_count
        return required_names, required_n, max_n
    except AttributeError:
        raise ValueError('Unable to introspect %s() arguments'
                            % getattr(func, '__name__', func))
